// Synthèses et exercices rédigés pour l’application à partir des thèmes des deux ouvrages.
// Les formulations, exemples et questions sont originaux ; les manuels ne sont pas reproduits.
const makeQuestions = (items) => items.map(([q, a, c, e], index) => {
  // Vary the correct-answer position so a whole section does not teach a guessing pattern.
  const shift = index % a.length;
  return { q, a: [...a.slice(shift), ...a.slice(0, shift)], c: (c - shift + a.length) % a.length, e };
});
const card = (title, lesson, prompt, questions) => ({ title, lesson, prompt, questions: makeQuestions(questions) });

